// Generated by Cypress Author on 2026-10-16.
import { mount } from "cypress/react";
import TaskWorkspace from "../../src/components/task-workspace";
import type { Task } from "../../src/lib/tasks";

const savedTask: Task = {
  id: 42,
  title: "Plan the launch",
  description: "Prepare a short launch checklist",
  priority: 3,
  dueDate: null,
  completed: false,
};

function mountWorkspace(tasks: Task[], total = tasks.length) {
  return mount(<TaskWorkspace initialTasks={tasks} initialTotal={total} />);
}

describe("Task workspace component", () => {
  it("creates a task from the dialog and refreshes the list", () => {
    let created: Task | undefined;
    cy.intercept("GET", "/api/tasks?*", (request) => {
      const tasks = created ? [created] : [];
      request.reply({
        statusCode: 200,
        body: { tasks, total: tasks.length, page: 1, limit: 20 },
      });
    }).as("listTasks");
    cy.intercept("POST", "/api/tasks", (request) => {
      expect(request.body).to.deep.equal({
        title: savedTask.title,
        description: "",
        priority: 3,
        dueDate: null,
      });
      created = { ...savedTask, description: "" };
      request.reply({ statusCode: 201, body: { task: created } });
    }).as("createTask");

    mountWorkspace([]);
    cy.wait("@listTasks");
    cy.contains("button", "New task").click();
    cy.get("dialog[open]").should("contain.text", "Create a task");
    cy.get("#dialog-title").type(savedTask.title);
    cy.contains("button", "Create task").click();

    cy.wait("@createTask");
    cy.contains("h3", savedTask.title).should("be.visible");
    cy.get(".task-card").should("contain.text", "Priority 3");
    cy.get(".task-card").should("not.contain.text", "Due ");
    cy.get("dialog[open]").should("not.exist");
  });

  it("edits a task in the dialog and shows the updated values", () => {
    let currentTask = { ...savedTask };
    cy.intercept("GET", "/api/tasks?*", (request) => {
      request.reply({
        statusCode: 200,
        body: { tasks: [currentTask], total: 1, page: 1, limit: 20 },
      });
    }).as("listTasks");
    cy.intercept("PATCH", `/api/tasks/${savedTask.id}`, (request) => {
      expect(request.body).to.deep.equal({
        title: "Plan the product launch",
        description: savedTask.description,
        priority: 3,
        dueDate: null,
      });
      currentTask = { id: savedTask.id, ...request.body };
      request.reply({ statusCode: 200, body: { task: currentTask } });
    }).as("updateTask");

    mountWorkspace([savedTask]);
    cy.wait("@listTasks");
    cy.get(`[aria-label="Edit ${savedTask.title}"]`).click();
    cy.get("dialog[open]").should("contain.text", "Edit task");
    cy.get("#dialog-title").should("have.value", savedTask.title).clear().type("Plan the product launch");
    cy.contains("button", "Save changes").click();

    cy.wait("@updateTask");
    cy.wait("@listTasks");
    cy.contains("h3", "Plan the product launch").should("be.visible");
    cy.get(".task-card").should("contain.text", "Priority 3");
    cy.get(".task-card").should("not.contain.text", "Due ");
    cy.contains("h3", savedTask.title).should("not.exist");
  });

  it("creates a task with a custom priority and due date", () => {
    const task: Task = {
      ...savedTask,
      id: 43,
      title: "File the release notes",
      priority: 1,
      dueDate: "2026-12-31",
    };
    let created: Task | undefined;
    cy.intercept("GET", "/api/tasks?*", (request) => {
      const tasks = created ? [created] : [];
      request.reply({ statusCode: 200, body: { tasks, total: tasks.length, page: 1, limit: 20 } });
    }).as("listTasks");
    cy.intercept("POST", "/api/tasks", (request) => {
      expect(request.body).to.deep.equal({
        title: task.title,
        description: "",
        priority: 1,
        dueDate: "2026-12-31",
      });
      created = task;
      request.reply({ statusCode: 201, body: { task } });
    }).as("createTaskWithOptionalFields");

    mountWorkspace([]);
    cy.wait("@listTasks");
    cy.contains("button", "New task").click();
    cy.get("#dialog-title").type(task.title);
    cy.get("#dialog-priority").select("1");
    cy.get("#dialog-due-date").type("2026-12-31");
    cy.contains("button", "Create task").click();

    cy.wait("@createTaskWithOptionalFields");
    cy.contains("h3", task.title).should("be.visible");
    cy.get(".task-card").should("contain.text", "Priority 1");
    cy.get(".task-card").should("contain.text", "Dec 31, 2026");
  });

  it("updates optional priority and due date values", () => {
    const taskWithOptionalFields: Task = {
      ...savedTask,
      priority: 4,
      dueDate: "2026-11-15",
    };
    let currentTask = { ...taskWithOptionalFields };
    cy.intercept("GET", "/api/tasks?*", (request) => {
      request.reply({
        statusCode: 200,
        body: { tasks: [currentTask], total: 1, page: 1, limit: 20 },
      });
    }).as("listTasks");
    cy.intercept("PATCH", `/api/tasks/${taskWithOptionalFields.id}`, (request) => {
      expect(request.body).to.deep.equal({
        title: taskWithOptionalFields.title,
        description: taskWithOptionalFields.description,
        priority: 1,
        dueDate: "2026-12-01",
      });
      currentTask = { id: taskWithOptionalFields.id, ...request.body };
      request.reply({ statusCode: 200, body: { task: currentTask } });
    }).as("updateOptionalFields");

    mountWorkspace([taskWithOptionalFields]);
    cy.wait("@listTasks");
    cy.get(`[aria-label="Edit ${taskWithOptionalFields.title}"]`).click();
    cy.get("#dialog-priority").select("1");
    cy.get("#dialog-due-date").clear().type("2026-12-01");
    cy.contains("button", "Save changes").click();

    cy.wait("@updateOptionalFields");
    cy.wait("@listTasks");
    cy.get(".task-card").should("contain.text", "Priority 1");
    cy.get(".task-card").should("contain.text", "Dec 1, 2026");
    cy.get(".task-card").should("not.contain.text", "Nov 15, 2026");
  });

  it("deletes a task after confirmation and shows the empty state", () => {
    let remainingTasks = [{ ...savedTask }];
    cy.intercept("GET", "/api/tasks?*", (request) => {
      request.reply({
        statusCode: 200,
        body: {
          tasks: remainingTasks,
          total: remainingTasks.length,
          page: 1,
          limit: 20,
        },
      });
    }).as("listTasks");
    cy.intercept("DELETE", `/api/tasks/${savedTask.id}`, (request) => {
      remainingTasks = [];
      request.reply({ statusCode: 204, body: "" });
    }).as("deleteTask");

    mountWorkspace([savedTask]);
    cy.wait("@listTasks");
    cy.get(`[aria-label="Delete ${savedTask.title}"]`).click();
    cy.get("dialog[open]").should("contain.text", "Delete this task?");
    cy.get("dialog[open]").should("contain.text", savedTask.title);
    cy.contains("dialog button", "Delete task").click();

    cy.wait("@deleteTask");
    cy.contains("h3", "Nothing on your list yet").should("be.visible");
    cy.contains("h3", savedTask.title).should("not.exist");
    cy.get("dialog[open]").should("not.exist");
  });

  it("toggles completion on and off with a filled green check", () => {
    let currentTask = { ...savedTask };
    cy.intercept("GET", "/api/tasks?*", (request) => {
      request.reply({
        statusCode: 200,
        body: { tasks: [currentTask], total: 1, page: 1, limit: 20 },
      });
    }).as("listTasks");
    cy.intercept("PATCH", `/api/tasks/${savedTask.id}/completion`, (request) => {
      const completed = request.body.completed as boolean;
      expect(completed).to.equal(!currentTask.completed);
      currentTask = { ...currentTask, completed };
      request.reply({ statusCode: 200, body: { task: currentTask } });
    }).as("toggleCompletion");

    mountWorkspace([savedTask]);
    cy.wait("@listTasks");

    cy.get(`[aria-label="Mark ${savedTask.title} as complete"]`)
      .should("have.attr", "aria-pressed", "false")
      .click();
    cy.wait("@toggleCompletion").its("request.body.completed").should("equal", true);
    cy.get(".task-card").should("have.class", "task-card-completed");
    cy.get(`[aria-label="Mark ${savedTask.title} as incomplete"]`)
      .should("have.attr", "aria-pressed", "true")
      .and("have.class", "is-completed");

    cy.get(`[aria-label="Mark ${savedTask.title} as incomplete"]`).click();
    cy.wait("@toggleCompletion").its("request.body.completed").should("equal", false);
    cy.get(".task-card").should("not.have.class", "task-card-completed");
    cy.get(`[aria-label="Mark ${savedTask.title} as complete"]`)
      .should("have.attr", "aria-pressed", "false")
      .and("not.have.class", "is-completed");
  });
});
